// FaceBlob is one rasterised face. `bold`, logical `size` and `raster_scale`
// are how the renderer picks between faces. `ascent` + `descent`
// is the height of a line. `parts` join into base64 of a metrics header
// (width, height, left bearing, top bearing, advance for each glyph)
// followed by every glyph's coverage bytes in the same order. It is split
// because a single literal this long, spelled as one concatenation,
// exceeds what V's checker will descend into.
struct FaceBlob {
	bold    bool
	mono    bool
	size    int
	raster_scale int
	ascent  int
	descent int
	parts   []string
}

